      "content": "package com.maplesure.claims;

import org.junit.jupiter.api.Test;

import java.math.BigDecimal;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class ClaimRulesTest {

    @Test
    void testDecideAccepted() {
        String decision = ClaimRules.decide("ACTIVE", new BigDecimal("10000"), new BigDecimal("500"), new BigDecimal("600"));
        assertEquals("ACCEPTED", decision);
    }

    @Test
    void testDecideRejectedBelowDeductible() {
        String decision = ClaimRules.decide("ACTIVE", new BigDecimal("10000"), new BigDecimal("500"), new BigDecimal("500"));
        assertEquals("REJECTED_BELOW_DEDUCTIBLE", decision);

        decision = ClaimRules.decide("ACTIVE", new BigDecimal("10000"), new BigDecimal("500"), new BigDecimal("499"));
        assertEquals("REJECTED_BELOW_DEDUCTIBLE", decision);
    }

    @Test
    void testDecideRejectedOverLimit() {
        String decision = ClaimRules.decide("ACTIVE", new BigDecimal("10000"), new BigDecimal("500"), new BigDecimal("10001"));
        assertEquals("REJECTED_OVER_LIMIT", decision);
    }

    @Test
    void testDecideRejectedPolicyStatus() {
        String decision = ClaimRules.decide("LAPSED", new BigDecimal("10000"), new BigDecimal("500"), new BigDecimal("600"));
        assertEquals("REJECTED_POLICY_LAPSED", decision);
    }

    @Test
    void testPayableCalculation() {
        BigDecimal payable = ClaimRules.payable(new BigDecimal("600"), new BigDecimal("500"));
        assertEquals(0, payable.compareTo(new BigDecimal("100")));

        payable = ClaimRules.payable(new BigDecimal("500"), new BigDecimal("600"));
        assertEquals(0, payable.compareTo(BigDecimal.ZERO));

        payable = ClaimRules.payable(new BigDecimal("600.0"), new BigDecimal("500"));
        assertTrue(payable.compareTo(new BigDecimal("100.0")) == 0);
    }
}"
